{paymentId&&!paymentDone&&!paymentProblem&&<><button className="mini-primary wide mini-payment-check-now" disabled={busy} onClick={()=>verify()}>{busy?'Checking every submitted reference…':'↻ Check payment status now'}</button><div className="mini-payment-next-ref">{paymentSubmittedAt&&clock-paymentSubmittedAt<150000?<><span className="mini-ref-countdown-label">OPTIONAL · NEW REFERENCE AVAILABLE IN</span><span className="mini-ref-countdown">{Math.floor((150000-(clock-paymentSubmittedAt))/60000)}:{String(Math.floor(((150000-(clock-paymentSubmittedAt))%60000)/1000)).padStart(2,'0')}</span><p>We are still checking your current transaction automatically. You do not need to submit anything again.</p></>:<><b>Still not verified? You have another option.</b><p>Submit a corrected transaction ID / hash if the first one was wrong. Your previous reference will <strong>keep being checked automatically</strong> unless it is verified.</p>{!showAlternateReference?<button className="mini-secondary wide" onClick={()=>{setShowAlternateReference(true);setReference('')}}>＋ Submit a different transaction reference</button>:<form onSubmit={submitPayment}><input className="mini-checkout-input" value={reference} onChange={e=>setReference(e.target.value)} placeholder={paymentMethod==='usdt'?'Paste the correct 64-character transaction hash':'Enter the correct Binance transaction ID'} required minLength={paymentMethod==='usdt'?64:5} maxLength={paymentMethod==='usdt'?64:128}/><div className="mini-payment-alt-actions"><button type="button" className="mini-secondary" onClick={()=>{setShowAlternateReference(false);setReference('')}}>Keep checking previous</button><button className="mini-primary" disabled={busy}>{busy?'Submitting…':'Submit corrected reference'}</button></div></form>}</>}</div></>}
